/**
 * The Cloudflare Worker entry (`main` in wrangler.jsonc).
 *
 * A thin wrapper around the Worker OpenNext builds: a few requests that never
 * need Next — the background video and bot probes — are answered first, in
 * about a millisecond, and everything else goes to Next untouched. See
 * `lib/edge/front-door.ts` for why (Error 1102, the 10ms CPU limit).
 *
 * This is OpenNext's documented "custom worker" pattern. `.open-next/worker.js`
 * exists only after `opennextjs-cloudflare build`, hence the ts-ignore.
 */

// @ts-ignore -- generated by `opennextjs-cloudflare build`
import { default as nextWorker } from "./.open-next/worker.js";
import { frontDoor, type AssetsBinding } from "./lib/edge/front-door";

// @ts-ignore -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";

interface Env {
  ASSETS?: AssetsBinding;
}

interface NextWorker {
  fetch(request: Request, env: Env, ctx: unknown): Promise<Response>;
}

export default {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const early = await frontDoor(request, env.ASSETS);
    if (early) return early;
    return (nextWorker as NextWorker).fetch(request, env, ctx);
  },
};
